```sql
CREATE PROCEDURE sp_update_alarm(IN alarm_id INT, IN action VARCHAR(20))
BEGIN
  DECLARE created_at TIMESTAMP DEFAULT NOW();

  DECLARE max_update_query VARCHAR(500);
  SET max_update_query = CONCAT('SELECT MAX(created_at) AS max_created_at FROM CriticalAlarmHistory WHERE alarm_id = ', CAST(alarm_id AS VARCHAR));

