    WHERE alarm_id = alarm_id;
END;
```

4. Finally, create a view to simplify querying `CriticalAlarmHistory`. Here's an example:

```sql
CREATE VIEW v_critical_alarm_history AS SELECT * FROM CriticalAlarmHistory WHERE action IN ('INSERT', 'UPDATE_MAX', 'DELETE');
