    premise_clauses = premise.split(". ")

    # Loop through each clause in the hypothesis
    for hypothesis_clause in hypothesis_clauses:
        found_entailment = False

        # Loop through each clause in the premise
        for premise_clause in premise_clauses:
            # Check if the hypothesis clause is a direct subset of the premise clause
            if hypothesis_clause.strip() and premise_clause.strip() and premise_clause.find(hypothesis_clause) != -1:
                found_entailment = True
                break

        # If no entailment was found, then premise does not entail hypothesis
        if not found_entailment:
            return False

    # If entailment was found for all clauses in hypothesis, then premise entails hypothesis
    return True

