        self.count = count
        self.next_biggest_sum = next_biggest_sum
        self.left = None
        self.right = None

class BST:
    def __init__(self):
        self.root = None

    def enqueue(self, x):
        self.root = self._enqueue(self.root, x)

    def dequeue(self):
        if self.root is None:
            raise ValueError("Queue is empty.")
        node = self._min_node(self.root)
        self.root = self._remove(self.root, node.value)
        return node.value

    def see_saw(self):
        return self._see_saw(self.root)

    def _enqueue(self, root, x):
        if root is None:
            return Node(x, 1, 1)

        if x == root.value:
            root.count += 1
            self._update_next_biggest_sum(root)
            return root

        if x < root.value:
            root.left = self._enqueue(root.left, x)
        else:
            root.right = self._enqueue(root.right, x)

        self._update_next_biggest_sum(root)
        return root

    def _min_node(self, root):
        while root.left is not None:
            root = root.left
        return root

    def _remove(self, root, x):
        if root is None:
            return None

        if x < root.value:
            root.left = self._remove(root.left, x)
        elif x > root.value:
            root.right = self._remove(root.right, x)
        else:
            if root.count == 1:
                if root.left is None:
                    temp = root.right
                    root = None
                    return temp
                elif root.right is None:
                    temp = root.left
                    root = None
                    return temp
                else:
                    temp = self._min_node(root.right)
                    root.value = temp.value
                    root.next_biggest_sum -= root.count
                    root.count = temp.count
                    root.right = self._remove(root.right, temp.value)
                    self._update_next_biggest_sum(root)

            root.count -= 1
            self._update_next_biggest_sum(root)
        return root

    def _see_saw(self, root):
        if root is None:
            return 0

        return root.count * (root.value + self._sum_right_subtree(root))

    def _sum_right_subtree(self, node):
        if node is None:
            return 0

        return (node.next_biggest_sum + node.value) * node.count + self._sum_right_subtree(node.right)

    def _update_next_biggest_sum(self, node):
        if node is None:
            return

        if node.left is None and node.right is None:
            node.next_biggest_sum = node.value
            return

        if node.left is None:
            node.next_biggest_sum = (node.value + node.right.next_biggest_sum) / (node.count + node.right.count)
        elif node.right is None:
            node.next_biggest_sum = (node.value + node.left.next_biggest_sum) / (node.count + node.left.count)
        else:
            node.next_biggest_sum = (node.value + node.left.next_biggest_sum + node.right.next_biggest_sum) / (node.count + node.left.count + node.right.count)
