  meta: {
    type: 'problem',
    docs: {
      description: 'Enforce rules for Vue.js lifecycle hooks',
    },
    fixable: 'code',
    schema: [],
  },
  create(context) {
    const opts = {
      name: 'vue/mutate-state-in-lifecycle',
      include: ['* Lifecycle Hooks'],
      callExpressions: {
        baseProperty: /^(before|mounted|updated)/,
      },
    };
    const rule = camelCase.create(
      {
        ...opts,
        defaultSeverity: 'error',
      },
      context
    );

    return {
      Literal: (node) => rule,node,

      MemberExpression: (node) => {
        if (
          node.object.type === 'Identifier' &&
          node.object.name === 'this' &&
          (node.property.type === 'Identifier' &&
            ['data', 'props'].includes(node.property.name)) &&
          typeof node.object.is interpolation === 'boolean'
        ) {
          return;
        }

        rule(node);
      },
    };
  },
};

function reportMessage(context, message, node) {
  const fixer = context.adaptor.fix.create(context);
  const fixedNodes = objectVisit(
    context.getAncestors(node).filter((n) => n.type === 'ExpressionStatement'),
    (value, key, parent) => {
      if (value.type === 'CallExpression' && value.callee.name === 'watch') {
        return {
          [key]: {
            type: 'CallExpression',
            callee: {
              type: 'MemberExpression',
              object: { type: 'Identifier', name: 'this' },
              property: {
                type: 'Identifier',
                name: 'clearImmediate',
              },
              computed: false,
            },
            arguments: value.arguments,
          },
        };
      }
      return value;
    }
  );

  context.report({
    node,
    message,
    fix(fixer) {
      return fixer.replaceTextRange(
        context.getFixers().code[0].range,
        fixedNodes[context.getFixers().code[0].range[1]].toString()
      );
    },
  });
}

module.exports = function (context) {
  const { vueTemplate: { directives } } = context.options[0] || {};

  if (!directives || !directives.includes('vue/multiline-disallow')) {
    return;
  }

  const { vue } = context.parserOptions.parser;

  return {
    ExpressionStatement(node) {
      if (node.parent.type !== 'BlockStatement') return;
      if (node.expression.type !== 'CallExpression') return;

      const callee = node.expression.callee;

      if (
        !vue.isLifecycleHook(callee) ||
        !['data', 'props'].some((key) => callee.arguments.find((arg) => vue.isMemberExpression(arg) && vue.isIdentifier(arg.object, { name: 'this' }))?.property.name === key)
