        return;
      }

      const dependsOnMutatingState = callee.arguments.some((arg) => {
        if (vue.isMemberExpression(arg)) {
          arg = arg.object;
        }

        if (vue.isAssignmentExpression({ operator: '=' })(arg)) {
          return true;
        }

        if (
          vue.isCallExpression(arg) &&
          (arg.callee.name === 'push' || arg.callee.name === 'splice') &&
          vue.isMemberExpression(arg.arguments[0]) &&
          vue.isIdentifier(arg.arguments[0].object, { name: 'this' }) &&
          ['data', 'props'].includes(arg.arguments[0].property.name)
        ) {
          return true;
        }

        return false;
      });

      if (dependsOnMutatingState) {
        reportMessage(context, 'Avoid mutating state in the {{Hook}} hook', node.expression);
      }
    },
  };
};
