  const onHookCodeFragment = onHookExp.range[1];

  const methodCallNodes = node.children.filter((node) => {
    const nodeStart = node.range[0];
    return nodeStart > onHookCodeFragment;
  });

  const methods = [];

  methodCallNodes.forEach((node) => {
    if (node.type === 'JSXElement' || node.type === 'JSXFragment') {
      methods.push(...getHookMethods(node));
    } else if (node.type === 'JSXExpressionContainer' && isJSXExpressionContainerMethodCall(node)) {
