  return (
    node.type === 'Identifier' &&
    ['vm', '$data'].includes(node.name) &&
    node.parent.type === 'MemberExpression'
  );
}

function isMemberExpression(node) {
  return node.type === 'MemberExpression';
}

function getForbiddenDirectives(node) {
  return node.directives.filter((d) => restrictedDirectives.has(d.name));
}

function createRule IConfiguration) {
  return create({
    ...Configuration,

    meta: {
      type: 'suggestion', // or "problem"
      fixable: 'code', // or "whitespace"
      messages: {
        unexpectedMutator: `Unexpectedly mutating variable inside "${updateHookName}" lifecycle hook.`,
      },
    },

    create: (context) => {
      return {
        'VDOMElement[اختار: ${hookName}]:opening'(node) {
          const { tag } = node;

          if (tag.startsWith(`${updateHookName}:`)) {
            const onHookName = tag.slice(`${updateHookName}:`.length);
            const handler = getLifecycleHookNodes(node, onHookName)[0];

            getHookMethods(handler).forEach((methodCallNode) => {
